            if (!scanner.hasNextLine()) {
                return;
            }
            String[] columns = scanner.nextLine().split(", ");
            List<Object> list = new ArrayList<>();
            for (int i = 0; i < columns.length; i++) {
                try {
                    int value = Integer.parseInt(columns[i]);
                    if (index == value) {
                        table.get(tableName).remove(list);
                    } else {
                        list.add(value);
                    }
                } catch (NumberFormatException e) {
                    System.out.println(e.getMessage());
                    return;
                }
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }

    private void updateValues(String tableName, String key, Map<String, Object> values) {
        for (Map.Entry<String, Object> entry : values.entrySet()) {
            if (!entry.getKey().equals(tableName)) {
                System.out.println("Error in column count or query.");
                return;
            }
            int index = new ArrayList<>(Arrays.asList(key)).indexOf(entry.getKey());
            table.get(tableName).set(index, entry.getValue());

            if (index > 0 && index < table.get(tableName).size() - 1) {
                updateValues(tableName, key, values);
            } else {
                System.out.println("Error in column count or query.");
            }
        }
    }

